mapper.select:
select r.id, r.activity_id, r.status, r.signup_time, r.checkin_time, r.checkin_type, a.title as activity_title, a.cover_url, a.location, a.start_time, a.end_time, a.signup_deadline, a.status as activity_status, case when exists ( select 1 from activity_review v where v.activity_id = r.activity_id and v.user_id = r.user_id ) then 1 else 0 end as reviewed from activity_registration r join activity a on a.id = r.activity_id where r.user_id = #{userId}
and r.status = #{q.status}
and a.status = #{q.activityStatus}
order by r.signup_time desc, r.id desc

select r.id, r.user_id, r.status, r.signup_time, r.checkin_time, r.checkin_type, u.username, u.real_name, u.student_no, u.phone from activity_registration r join sys_user u on u.id = r.user_id where r.activity_id = #{activityId}
and r.status = #{q.status}
and (u.real_name like concat('%', #{q.keyword}, '%') or u.username like concat('%', #{q.keyword}, '%') or u.student_no like concat('%', #{q.keyword}, '%'))
order by r.signup_time asc, r.id asc

select r.id, r.user_id, r.status, r.signup_time, r.checkin_time, r.checkin_type, u.username, u.real_name, u.student_no, u.phone from activity_registration r join sys_user u on u.id = r.user_id where r.activity_id = #{activityId}
and r.status = #{status}
and (u.real_name like concat('%', #{keyword}, '%') or u.username like concat('%', #{keyword}, '%') or u.student_no like concat('%', #{keyword}, '%'))
order by r.checkin_time asc, r.id asc
